<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>EMBERLINE — Tactical FPS</title>
<style>
  /* Palette: dusk foundry. Amber = Vanguard (attackers), steel cyan = Sentinel (defenders). */
  :root {
    --canvas: #14161a;
    --surface: #1e2228;
    --hairline: #2c323a;
    --ink: #e9e6df;
    --muted: #98a0a8;
    --accent: #f0a830;
    --foe: #57b8c9;
    --danger: #e4572e;
    --radius-panel: 4px;
    --radius-control: 8px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: var(--canvas);
    color: var(--ink);
    font-family: var(--font-ui);
    user-select: none;
  }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }
  #vignette { position: fixed; inset: 0; pointer-events: none;
    background: radial-gradient(ellipse at center, transparent 58%, rgba(10,10,12,.55) 100%); }
  #damage-flash { position: fixed; inset: 0; pointer-events: none; opacity: 0;
    background: radial-gradient(ellipse at center, transparent 45%, rgba(228,87,46,.5) 100%); }
  #flash-white { position: fixed; inset: 0; pointer-events: none; opacity: 0; background: #fff; }

  /* Crosshair: four ticks that spread with the weapon's current spread. */
  #crosshair { position: fixed; left: 50%; top: 50%; width: 0; height: 0; }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; }
  #crosshair i:nth-child(1) { left: -1px; width: 2px; height: 8px; }
  #crosshair i:nth-child(2) { left: -1px; width: 2px; height: 8px; }
  #crosshair i:nth-child(3) { top: -1px; height: 2px; width: 8px; }
  #crosshair i:nth-child(4) { top: -1px; height: 2px; width: 8px; }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px;
    transform: translate(-50%, -50%) rotate(45deg); opacity: 0; transition: opacity 90ms linear; }
  #hitmarker.on { opacity: 1; }
  #hitmarker.kill i { background: var(--danger); }
  #hitmarker i { position: absolute; background: var(--accent); }
  #hitmarker i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #hitmarker i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }

  /* Top bar: round timer, score, team pips. */
  #topbar { position: fixed; top: 18px; left: 50%; transform: translateX(-50%);
    display: flex; align-items: center; gap: 14px; font-family: var(--font-readout); }
  #topbar .team { display: flex; align-items: center; gap: 6px; font-size: 13px; color: var(--muted); }
  #topbar .team b { font-size: 22px; color: var(--ink); font-weight: 600; }
  #topbar .team.van b { color: var(--accent); }
  #topbar .team.sen b { color: var(--foe); }
  .pips { display: flex; gap: 3px; }
  .pips i { width: 8px; height: 8px; border-radius: 50%; background: var(--hairline); }
  .pips i.alive.van { background: var(--accent); }
  .pips i.alive.sen { background: var(--foe); }
  #timer { font-size: 22px; color: var(--ink); min-width: 58px; text-align: center; }
  #timer.low { color: var(--danger); }
  #round-label { position: fixed; top: 48px; left: 50%; transform: translateX(-50%);
    font-family: var(--font-readout); font-size: 11px; letter-spacing: .14em; color: var(--muted); text-transform: uppercase; }

  /* Bottom left: health + armor. Bottom right: ammo + money + weapon. */
  #vitals { position: fixed; left: 32px; bottom: 24px; font-family: var(--font-readout); }
  #health { font-size: 52px; line-height: 1; letter-spacing: -0.03em; }
