  #money-line { margin-top: 6px; font-size: 13px; color: var(--muted); }
  #money-line b { color: var(--accent); font-weight: 600; }
  #grenades { margin-top: 4px; font-size: 12px; color: var(--muted); }

  /* Killfeed, top right. */
  #killfeed { position: fixed; top: 18px; right: 24px; display: flex; flex-direction: column;
    gap: 4px; align-items: flex-end; font-family: var(--font-readout); font-size: 12px; }
  #killfeed div { background: color-mix(in srgb, var(--surface) 82%, transparent);
    border: 1px solid var(--hairline); border-radius: var(--radius-panel); padding: 4px 8px; }
  #killfeed .van { color: var(--accent); }
  #killfeed .sen { color: var(--foe); }
  #killfeed .hs { color: var(--danger); }

  /* Objective banner: plant/defuse progress + site callouts. */
  #objective { position: fixed; top: 84px; left: 50%; transform: translateX(-50%);
    font-family: var(--font-readout); font-size: 13px; color: var(--ink); text-align: center; }
  #objective .site { color: var(--accent); }
  #progress-wrap { width: 220px; height: 6px; background: var(--hairline); margin: 8px auto 0; border-radius: 3px; }
  #progress-fill { height: 100%; width: 0; background: var(--accent); border-radius: 3px; }
  #progress-label { font-size: 11px; color: var(--muted); margin-top: 4px; letter-spacing: .1em; text-transform: uppercase; }

  /* Buy menu (B during the buy phase). */
  #buy { position: fixed; inset: 0; display: grid; place-items: center; pointer-events: auto; }
  #buy[hidden] { display: none; }
  #buy .panel { width: min(560px, 94vw); background: var(--surface); border: 1px solid var(--hairline);
    border-radius: var(--radius-panel); padding: 24px 28px; }
  #buy h2 { margin: 0 0 4px; font-size: 22px; font-weight: 500; }
  #buy .sub { margin: 0 0 16px; font-size: 13px; color: var(--muted); }
  #buy .sub b { color: var(--accent); }
  .buy-row { display: flex; align-items: center; gap: 12px; padding: 9px 10px;
    border: 1px solid var(--hairline); border-radius: var(--radius-panel); margin-bottom: 8px; cursor: pointer; }
  .buy-row:hover { border-color: var(--accent); }
  .buy-row.owned { opacity: .55; cursor: default; }
  .buy-row.owned:hover { border-color: var(--hairline); }
  .buy-row .key { font-family: var(--font-readout); font-size: 12px; color: var(--muted);
    border: 1px solid var(--hairline); border-radius: 4px; padding: 2px 7px; min-width: 26px; text-align: center; }
  .buy-row .name { flex: 1; }
  .buy-row .name b { display: block; font-weight: 500; font-size: 14px; }
  .buy-row .name span { font-size: 12px; color: var(--muted); }
  .buy-row .price { font-family: var(--font-readout); color: var(--accent); font-size: 14px; }
  .buy-row.cant .price { color: var(--danger); }

  /* Full-screen overlays: menu, pause, round end, match end. */
  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px;
    background: color-mix(in srgb, var(--canvas) 84%, transparent); }
  .overlay[hidden] { display: none; }
  .panel { width: min(460px, 100%); padding: 32px; background: var(--surface);
    border: 1px solid var(--hairline); border-radius: var(--radius-panel); }
  .panel h1 { margin: 0 0 8px; font-size: 32px; line-height: 1.15; font-weight: 500; letter-spacing: -0.02em; }
  .panel h1 .amber { color: var(--accent); }
  .panel p { margin: 0 0 24px; max-width: 46ch; font-size: 15px; line-height: 1.55; color: var(--muted); }
  .panel p b { color: var(--ink); font-weight: 500; }
  .bigbtn { font: inherit; font-weight: 500; padding: 12px 18px; border: 1px solid var(--accent);
    border-radius: var(--radius-control); background: var(--accent); color: var(--canvas); cursor: pointer; }
  .bigbtn:hover { background: var(--ink); border-color: var(--ink); }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 13px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
  .keys kbd { min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline);
    border-radius: var(--radius-panel); font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center; }
  #round-result { font-family: var(--font-readout); font-size: 13px; color: var(--muted); margin-bottom: 16px; }
  #round-result b { color: var(--ink); }
  .score-line { font-family: var(--font-readout); font-size: 15px; margin-bottom: 20px; }
  .score-line .van { color: var(--accent); }
  .score-line .sen { color: var(--foe); }
</style>
</head>
