    hud.setObjective('Plant the charge at Site A or Site B — or eliminate Sentinel.');
    settle(10);
    aimAt(new THREE.Vector3(-8, 1.35, -4));
    shoot(0);
    settle(4);
    shoot(0);
    settle(4);
    aimAt(new THREE.Vector3(-8, 1.35, -4));
    shoot(0);
    settle(4);
    aimAt(new THREE.Vector3(-8, 1.35, -4));
