  // Ground and perimeter: 44 x 34 m, 5 m walls, open sky.
  box(44.4, 0.4, 34.4, 0, -0.2, 0, 'floor');
  box(0.4, 5, 34.4, -22.2, 2.5, 0, 'wall');
