  box(3.2, 1.1, 1.2, -12, 0.55, 4, 'crate');
  box(1.2, 1.1, 3.4, -16, 0.55, -1, 'crate');
  box(6.0, 2.6, 2.2, -18.5, 1.3, -4.5, 'rust');
  box(2.2, 2.6, 1.2, -8.5, 1.3, -6.5, 'crate');
