  const fill = new THREE.DirectionalLight(new THREE.Color(PALETTE.foe), 0.4);
  fill.position.set(-12, 10, -14);
  scene.add(fill);

  return {
    colliders,
    shootables,
    group,
    sites: SITES,
    waypoints: WAYPOINTS,
    routes: ROUTES,
    vanSpawn: new THREE.Vector3(0, 0, 13.5),
    senSpawn: new THREE.Vector3(0, 0, -13.5),
  };
}
