      state.reloadLeft = def.reload;
    },
    spread(speed) {
      const moving = Math.min(1, speed / MOVE_REFERENCE);
      return def.spreadStill + moving * def.spreadMove + state.burst * 0.012;
    },
    refill() {
      state.mag = def.mag;
      state.reserve = def.reserve;
      state.cooldown = 0;
      state.reloadLeft = 0;
      state.flash = 0;
      state.kick = 0;
      state.burst = 0;
    },
  };
}
